const canvas=document.getElementById('starfield'),ctx=canvas.getContext('2d');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let width=0,height=0,frame=0,stars=[],last=0;
let seed=4217;const rand=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646;};
const clusters=[{x:.13,y:.26},{x:.86,y:.23},{x:.11,y:.78},{x:.88,y:.72},{x:.48,y:.06}];
function resize(){width=innerWidth;height=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=width*d;canvas.height=height*d;ctx.setTransform(d,0,0,d,0,0);seed=4217;stars=Array.from({length:180},(_,i)=>({cluster:i%5,angle:rand()*Math.PI*2,radius:15+rand()*140,phase:rand()*6.28,size:rand()<.08?1.5:rand()*.7+.25,warm:rand()>.38,drift:rand(),farX:rand(),farY:rand()}));draw(0);}
function point(s,t){const c=clusters[s.cluster],gather=.55+.22*Math.sin(t*.065+s.cluster*1.6);const a=s.angle+t*.008*(s.cluster%2?1:-1);return{x:width*c.x+Math.cos(a)*s.radius*gather+(s.farX-.5)*110*(1-gather),y:height*c.y+Math.sin(a)*s.radius*gather+(s.farY-.5)*100*(1-gather)};}
function draw(t){ctx.clearRect(0,0,width,height);const glow=ctx.createRadialGradient(width*.5,height*.06,0,width*.5,height*.06,width*.65);glow.addColorStop(0,'rgba(25,48,68,.22)');glow.addColorStop(1,'rgba(3,5,7,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);const pts=stars.map(s=>point(s,t));for(let i=0;i<stars.length;i++){const s=stars[i],p=pts[i],alpha=.22+.48*(.5+.5*Math.sin(t*.6+s.phase));if(i<30){for(let j=i+5;j<Math.min(40,stars.length);j+=5){const q=pts[j],distance=Math.hypot(p.x-q.x,p.y-q.y);if(distance<65&&distance>18){ctx.strokeStyle=`rgba(126,151,168,${.065*(1-distance/65)})`;ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();}}}const color=s.warm?'220,210,169':'151,177,198';if(s.size>1.2){const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,9);g.addColorStop(0,`rgba(${color},${alpha*.35})`);g.addColorStop(1,`rgba(${color},0)`);ctx.fillStyle=g;ctx.fillRect(p.x-9,p.y-9,18,18);ctx.strokeStyle=`rgba(${color},${alpha*.22})`;ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(p.x-4,p.y);ctx.lineTo(p.x+4,p.y);ctx.moveTo(p.x,p.y-4);ctx.lineTo(p.x,p.y+4);ctx.stroke();}ctx.fillStyle=`rgba(${color},${alpha})`;ctx.beginPath();ctx.arc(p.x,p.y,s.size,0,Math.PI*2);ctx.fill();}}
function loop(now){if(now-last>32){draw(now/1000);last=now;}frame=requestAnimationFrame(loop);}
function start(){cancelAnimationFrame(frame);if(!reduced.matches&&!document.hidden)frame=requestAnimationFrame(loop);else draw(0);}
addEventListener('resize',resize);document.addEventListener('visibilitychange',start);reduced.addEventListener('change',start);resize();start();
